import { seatRule, gridRule } from './rules.ts';
import type { Input, Problem, Rule } from './rules.ts';

// run() reads this.rules — it only works when called ON a validator.
export type Validator = {
  name: string;
  rules: readonly Rule[];
  run(input: Input): Problem[];
};

export const validator: Validator = {
  name: 'booking-form',
  rules: [seatRule, gridRule],
  run(input) {
    const found: Problem[] = [];
    for (const rule of this.rules) {
      const p = rule(input);
      if (p !== null) found.push(p);
    }
    return found;
  },
};

// LabFlow booking rules (lesson 3.4). A rule looks at a booking input and returns a problem, or null.
export type Input = { lab: string; seats: number; start: string; end: string };
export type Problem = { code: string; message: string };
export type Rule = (input: Input) => Problem | null;

export const seatRule: Rule = ({ seats }) => (seats > 40 ? { code: 'TOO_MANY_SEATS', message: 'At most 40 seats' } : null);
export const gridRule: Rule = ({ start }) => (start.endsWith(':00') || start.endsWith(':30') ? null : { code: 'OFF_GRID', message: start + ' is off the grid' });

import { validator } from '../src/validator.ts';
import type { Input } from '../src/rules.ts';

const input: Input = { lab: 'BE-201', seats: 45, start: '08:15', end: '10:00' };
validator.run(input);
validator.run.call(validator, input);
const bound = validator.run.bind(validator);
bound(input);
[input].map((i) => validator.run(i));

import { validator } from '../src/validator.ts';
import type { Input } from '../src/rules.ts';

const input: Input = { lab: 'BE-201', seats: 45, start: '08:15', end: '10:00' };
const run = validator.run;
run(input); // expect TS2684

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { validator } from '../src/validator.ts';

test('run finds both problems of a 45-seat booking at 08:15', () => {
  const codes = validator.run({ lab: 'BE-201', seats: 45, start: '08:15', end: '10:00' }).map((p) => p.code);
  assert.deepEqual(codes, ['TOO_MANY_SEATS', 'OFF_GRID']);
});

