import type { Input, Problem, Rule } from './rules.ts';

export type Validator = { name: string; run: (input: Input) => Problem[] };

// Build a validator for a list of rules. Today run() reads this.rules,
// so "const run = v.run" or "[input].map(v.run)" crash at runtime.
export function createValidator(name: string, rules: readonly Rule[]): Validator {
  return {
    name,
    rules,
    run(input: Input): Problem[] {
      const found: Problem[] = [];
      for (const rule of this.rules) {
        const p = rule(input);
        if (p !== null) found.push(p);
      }
      return found;
    },
  };
}

// LabFlow booking rules (lesson 3.4). A rule looks at a booking input and returns a problem, or null.
export type Input = { lab: string; seats: number; start: string; end: string };
export type Problem = { code: string; message: string };
export type Rule = (input: Input) => Problem | null;

export const seatRule: Rule = ({ seats }) => (seats > 40 ? { code: 'TOO_MANY_SEATS', message: 'At most 40 seats' } : null);
export const gridRule: Rule = ({ start }) => (start.endsWith(':00') || start.endsWith(':30') ? null : { code: 'OFF_GRID', message: start + ' is off the grid' });

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createValidator } from '../src/validator.ts';
import { seatRule, gridRule } from '../src/rules.ts';
import type { Input } from '../src/rules.ts';

const v = createValidator('booking-form', [seatRule, gridRule]);
const input: Input = { lab: 'BE-201', seats: 45, start: '08:15', end: '10:00' };

test('run as a method', () => assert.equal(v.run(input).length, 2));
test('run taken off the object', () => {
  const run = v.run;
  assert.deepEqual(run(input).map((p) => p.code), ['TOO_MANY_SEATS', 'OFF_GRID']);
});
test('run passed to map', () => assert.deepEqual([input].map(v.run).map((ps) => ps.length), [2]));
test('run passed to setTimeout', async () => {
  const later = await new Promise<number>((done) => setTimeout((i: Input) => done(v.run(i).length), 0, input));
  assert.equal(later, 2);
});
test('a valid booking has no problems', () => assert.deepEqual(v.run({ lab: 'BE-201', seats: 30, start: '08:00', end: '10:00' }), []));

