import type { Input, Problem } from './rules.ts';

// A tiny form API, Express-style: register handlers, run them all on submit.
export type Handler = (input: Input) => Problem[];

const handlers: Handler[] = [];

export function onSubmit(handler: Handler): void {
  handlers.push(handler);
}

export function submit(input: Input): Problem[] {
  const all: Problem[] = [];
  for (const handler of handlers) all.push(...handler(input));
  return all;
}

// LabFlow booking rules (lesson 3.4). A rule looks at a booking input and returns a problem, or null.
export type Input = { lab: string; seats: number; start: string; end: string };
export type Problem = { code: string; message: string };
export type Rule = (input: Input) => Problem | null;

export const seatRule: Rule = ({ seats }) => (seats > 40 ? { code: 'TOO_MANY_SEATS', message: 'At most 40 seats' } : null);
export const gridRule: Rule = ({ start }) => (start.endsWith(':00') || start.endsWith(':30') ? null : { code: 'OFF_GRID', message: start + ' is off the grid' });

import { seatRule, gridRule } from './rules.ts';
import type { Input, Problem, Rule } from './rules.ts';

export type Validator = { rules: readonly Rule[]; run(this: Validator, input: Input): Problem[] };

export const validator: Validator = {
  rules: [seatRule, gridRule],
  run(input) {
    const found: Problem[] = [];
    for (const rule of this.rules) {
      const p = rule(input);
      if (p !== null) found.push(p);
    }
    return found;
  },
};

import { onSubmit } from '../src/form.ts';
import { validator } from '../src/validator.ts';
import type { Input, Problem } from '../src/rules.ts';

onSubmit((input) => validator.run(input));
function noWeekendLabs(input: Input): Problem[] {
  return input.lab === 'WEEKEND' ? [{ code: 'CLOSED', message: 'Closed' }] : [];
}
onSubmit(noWeekendLabs);

import { onSubmit } from '../src/form.ts';
import { validator } from '../src/validator.ts';

onSubmit(validator.run); // expect TS2345

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { onSubmit, submit } from '../src/form.ts';
import { validator } from '../src/validator.ts';

test('submit runs every handler and joins their problems', () => {
  onSubmit((input) => validator.run(input));
  onSubmit((input) => (input.lab === 'BE-201' ? [] : [{ code: 'UNKNOWN_LAB', message: 'No such lab' }]));
  const codes = submit({ lab: 'XX-1', seats: 45, start: '08:15', end: '10:00' }).map((p) => p.code);
  assert.deepEqual(codes, ['TOO_MANY_SEATS', 'OFF_GRID', 'UNKNOWN_LAB']);
});

