// this: void = "I will call you as a plain function, with no object in front".
// A method that needs this: Validator is then refused at onSubmit (TS2345).
export type Handler = (this: void, input: Input) => Problem[];

const handlers: Handler[] = [];

export function onSubmit(handler: Handler): void {
  handlers.push(handler);
}

export function submit(input: Input): Problem[] {
  const all: Problem[] = [];
  for (const handler of handlers) all.push(...handler(input));
  return all;
}

